l":{"uk":"ESMO: мантійноклітинна лімфома, клінічна настанова (MIPI і MIPI-c, табл. 3)","en":"ESMO Clinical Practice Guidelines: mantle cell lymphoma (MIPI and MIPI-c, Table 3)"},"version":"Ann Oncol 2017;28(Suppl 4):iv62-71","updated":"2017-08-01"},{"kind":"other","url":"https://www.esmo.org/guidelines/living-guidelines/esmo-living-guideline-lymphomas","label":{"uk":"ESMO Living Guideline: лімфоми","en":"ESMO Living Guideline: Lymphomas"},"version":"v1.1","updated":"2026-02-01"}]}]$catalog$::jsonb)
